const crypto = require('crypto');
const root = $input.item.json || {};
const body = root.body && typeof root.body === 'object' ? root.body : root;
const pick = (...keys) => {
  for (const key of keys) {
    const value = body[key];
    if (value !== undefined && value !== null && String(value).trim() !== '') return String(value).trim();
  }
  return '';
};
const collapse = (s) => String(s || '').replace(/\s+/g, ' ').trim();
const promptEscape = (value) => String(value ?? '')
  .replace(/<[^>]{0,500}>/g, '[html-tag-redacted-for-model-transport]')
  .replace(/\bon\w+\s*=/gi, '[html-event-attr-redacted]=')
  .replace(/\bscript\b/gi, '[script-redacted]')
  .replace(/[&<>]/g, ch => ({
  '&': '&amp;',
  '<': '&lt;',
  '>': '&gt;',
}[ch]));
const name = collapse(pick('name', 'Name', 'fullName', 'full_name'));
const company = collapse(pick('company', 'Company'));
const email = collapse(pick('email', 'Email')).toLowerCase();
const raw_needs = collapse(pick('process_hurts', 'processHurts', 'message', 'needs', 'Needs', 'what_hurts'));
const source = collapse(pick('source')) || 'n8n-direct-lead-test';
const email_ok = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
const reasons = [];
if (!company) reasons.push('company missing');
if (!email_ok) reasons.push('email invalid');
if (raw_needs.length < 20) reasons.push('needs text too short');
if (raw_needs.length > 5000) reasons.push('needs text too long');
const sensitive_patterns = [
  { label: 'secret_or_token', re: /(api[_ -]?key|token|password|passwd|secret|sk-[a-z0-9_-]{10,})/i },
  { label: 'payment_data', re: /(credit card|card number|cvv|iban|swift|routing number)/i },
  { label: 'health_or_legal_sensitive', re: /(diagnosis|medical record|patient|lawsuit|criminal|passport|ssn|social security)/i },
];
const sensitivity_flags = sensitive_patterns.filter(p => p.re.test(raw_needs)).map(p => p.label);
const submission_id = crypto.createHash('sha256').update(email + '\n' + raw_needs, 'utf8').digest('hex');
const valid_input = reasons.length === 0;
return {
  json: {
    submission_id,
    valid_input,
    validation_errors: reasons,
    sensitive_held: sensitivity_flags.length > 0,
    sensitivity_flags,
    name,
    company,
    email,
    raw_needs,
    ai_prompt_needs: promptEscape(raw_needs),
    source,
    created_at: new Date().toISOString(),
    model_version: 'gpt-4o-mini|lead_qualification|v1',
    execution_id: $execution.id,
  },
};

